'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var Float32Array = require( '@stdlib/array/float32' );
var Uint8Array = require( '@stdlib/array/uint8' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {string} dtype - data type
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( dtype, buffer, length, stride, offset ) {
	return new ndarray( dtype, buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	var smskrange = require( './../lib' );
	t.ok( true, __filename );
	t.strictEqual( typeof smskrange, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	var smskrange = require( './../lib' );
	t.strictEqual( smskrange.length, 1, 'has expected arity' );
	t.end();
});

tape( 'if a native implementation is available, the main export is the native implementation', function test( t ) {
	var smskrange = proxyquire( './../lib', {
		'@stdlib/utils/try-require': tryRequire
	});

	t.strictEqual( smskrange.main, require( './../lib/main.js' ), 'has main export' );
	t.end();

	function tryRequire() {
		return mock;
	}

	function mock() {
		// Mock...
	}
});

tape( 'if a native implementation is not available, the main export is the JavaScript implementation', function test( t ) {
	var smskrange = proxyquire( './../lib', {
		'@stdlib/utils/try-require': tryRequire
	});
	var main = require( './../lib/main.js' );

	t.strictEqual( smskrange, main, 'returns expected value' );
	t.strictEqual( smskrange.main, main, 'has main export' );
	t.end();

	function tryRequire() {
		return new Error( 'cannot load native addon' );
	}
});

tape( 'the function calculates the range value of a one-dimensional ndarray according to a mask', function test( t ) {
	var smskrange = require( './../lib' );
	var mask;
	var x;
	var v;

	x = new Float32Array( [ 1.0, -2.0, -4.0, NaN, 5.0, 0.0, 3.0 ] );
	mask = new Uint8Array( [ 0, 0, 0, 1, 0, 0, 0 ] );
	v = smskrange( [ vector( 'float32', x, x.length, 1, 0 ), vector( 'uint8', mask, mask.length, 1, 0 ) ] );
	t.strictEqual( v, 9.0, 'returns expected value' );

	t.end();
});
